// bootstrapDesignCenterOnce returns the result of ensure for key, running it
// under the bootstrap lock only the first time key is requested. Nothing is
// created when replaying VCR cassettes; replayValue is returned instead.
func bootstrapDesignCenterOnce(t *testing.T, key, replayValue string, ensure func(*transport_tpg.Config) string) string {
	t.Helper()

	if os.Getenv("VCR_MODE") == "REPLAYING" {
		return replayValue
	}
	config := transport_tpg.BootstrapConfig(t)
	if config == nil {
		return ""
	}

	bootstrapDesignCenterMu.Lock()
	defer bootstrapDesignCenterMu.Unlock()

	if value, ok := bootstrapDesignCenterCache[key]; ok {
		return value
	}
	value := ensure(config)
	bootstrapDesignCenterCache[key] = value
	return value
}

// ensureDesignCenterResource creates the Design Center resource called name
// unless it already exists. If exclusive is set, the parent allows only one
// such resource, so leftovers from previous runs are deleted before creating.
func ensureDesignCenterResource(t *testing.T, config *transport_tpg.Config, project, name, idParam string, exclusive bool, body map[string]interface{}) {
	t.Helper()

	_, err := designCenterBootstrapRequest(config, project, "GET", bootstrapDesignCenterBaseURL+name, nil)
	if err == nil {
		return
	}
	if !transport_tpg.IsGoogleApiErrorWithCode(err, 404) {
		t.Fatalf("Bootstrapping failed. Error getting Design Center resource %s: %s", name, err)
	}

	i := strings.LastIndex(name, "/")
	collection, id := name[:i], name[i+1:]
	if exclusive {
		cleanupDesignCenterResources(t, config, project, collection, true)
	}
	op, err := designCenterBootstrapRequest(config, project, "POST", fmt.Sprintf("%s%s?%s=%s", bootstrapDesignCenterBaseURL, collection, idParam, id), body)
	if err != nil && !transport_tpg.IsGoogleApiErrorWithCode(err, 409) {
		t.Fatalf("Bootstrapping failed. Error creating Design Center resource %s: %s", name, err)
	}
	waitForDesignCenterBootstrapOperation(t, config, project, bootstrapDesignCenterBaseURL, op)
}

// cleanupDesignCenterResources deletes every resource in collection (for
// example projects/p/locations/l/spaces) left over from previous failed or
// interrupted test runs. Otherwise creating a new one fails: only one Space is
// allowed per region within a management project (409), one Catalog per Space
// (FAILED_PRECONDITION), one Share per Catalog (CATALOG_ALREADY_SHARED), and
// one Connection between two Components ("connection already exists").
func cleanupDesignCenterResources(t *testing.T, config *transport_tpg.Config, project, collection string, force bool) {
	t.Helper()

	res, err := designCenterBootstrapRequest(config, project, "GET", bootstrapDesignCenterBaseURL+collection, nil)
	if err != nil {
		if transport_tpg.IsGoogleApiErrorWithCode(err, 404) {
			return
		}
		t.Fatalf("Bootstrapping failed. Error listing Design Center resources in %s: %s", collection, err)
	}

	items, _ := res[collection[strings.LastIndex(collection, "/")+1:]].([]interface{})
	for _, item := range items {
		resource, _ := item.(map[string]interface{})
		name, _ := resource["name"].(string)
		if name == "" {
			continue
		}
		deleteURL := bootstrapDesignCenterBaseURL + name
		if force {
			deleteURL += "?force=true"
		}
		log.Printf("[DEBUG] Deleting leftover Design Center resource %s before test", name)
		op, err := designCenterBootstrapRequest(config, project, "DELETE", deleteURL, nil)
		if err != nil && !transport_tpg.IsGoogleApiErrorWithCode(err, 404) {
			t.Fatalf("Bootstrapping failed. Error deleting leftover Design Center resource %s: %s", name, err)
		}
		waitForDesignCenterBootstrapOperation(t, config, project, bootstrapDesignCenterBaseURL, op)
	}
}

// ensureDesignCenterAppHubBoundary makes project an App Hub management project
// by setting its App Hub boundary crmNode to the project itself.
func ensureDesignCenterAppHubBoundary(t *testing.T, config *transport_tpg.Config, project, number string) {
	t.Helper()

	boundaryURL := fmt.Sprintf("%sprojects/%s/locations/global/boundary", bootstrapDesignCenterAppHubBaseURL, project)
	res, err := designCenterBootstrapRequest(config, project, "GET", boundaryURL, nil)
	if err != nil {
		t.Fatalf("Bootstrapping failed. Error getting App Hub boundary %s: %s", boundaryURL, err)
	}

	crmNode := "projects/" + number
	if res["crmNode"] == crmNode {
		return
	}

	log.Printf("[DEBUG] Setting App Hub boundary of %s to %s", project, crmNode)
	op, err := designCenterBootstrapRequest(config, project, "PATCH", boundaryURL+"?updateMask=crmNode", map[string]interface{}{"crmNode": crmNode})
	if err != nil {
		t.Fatalf("Bootstrapping failed. Error patching App Hub boundary %s: %s", boundaryURL, err)
	}
	waitForDesignCenterBootstrapOperation(t, config, project, bootstrapDesignCenterAppHubBaseURL, op)
}

// waitForDesignCenterBootstrapOperation polls op until it completes if it is a
// long-running operation served from baseURL. Synchronous responses are ignored.
func waitForDesignCenterBootstrapOperation(t *testing.T, config *transport_tpg.Config, project, baseURL string, op map[string]interface{}) {
	t.Helper()

	name, _ := op["name"].(string)
	if !strings.Contains(name, "/operations/") {
		return
	}

	deadline := time.Now().Add(5 * time.Minute)
	for {
		res, err := designCenterBootstrapRequest(config, project, "GET", baseURL+name, nil)
		if err != nil {
			t.Fatalf("Bootstrapping failed. Error waiting for operation %s: %s", name, err)
		}
		if done, _ := res["done"].(bool); done {
			if e, ok := res["error"]; ok {
				t.Fatalf("Bootstrapping failed. Operation %s failed: %v", name, e)
			}
			return
		}
		if time.Now().After(deadline) {
			t.Fatalf("Bootstrapping failed. Timed out waiting for operation %s", name)
		}
		time.Sleep(5 * time.Second)
	}
}

// designCenterBootstrapRequest sends a bootstrap REST request, retrying the
// errors matched by isDesignCenterBootstrapRetryableError.
func designCenterBootstrapRequest(config *transport_tpg.Config, project, method, url string, body map[string]interface{}) (map[string]interface{}, error) {
	return transport_tpg.SendRequest(transport_tpg.SendRequestOptions{
		Config:               config,
		Method:               method,
		Project:              project,
		RawURL:               url,
		UserAgent:            config.UserAgent,
		Body:                 body,
		Timeout:              5 * time.Minute,
		ErrorRetryPredicates: []transport_tpg.RetryErrorPredicateFunc{isDesignCenterBootstrapRetryableError},
	})
}

// isDesignCenterBootstrapRetryableError retries while IAM permissions and
// service activation propagate in a freshly bootstrapped project, and while the
// Design Center service agent, which is provisioned on first use, replicates
// (the error IsDesignCenterServiceAgentNotFoundError retries for the Space
// resource). This is why no generateServiceIdentity call is needed.
func isDesignCenterBootstrapRetryableError(err error) (bool, string) {
	if err == nil {
		return false, ""
	}
	if transport_tpg.IsGoogleApiErrorWithCode(err, 403) {
		return true, "Waiting for project IAM permissions and service activation to propagate"
	}
	msg := err.Error()
	if strings.Contains(msg, "gcp-sa-designcenter.iam.gserviceaccount.com") &&
		strings.Contains(msg, "ServiceAccountInfoDataType") {
		return true, "Waiting for Design Center service agent to propagate"
	}
	return false, ""
}
